    test('[TC_REQRES_APP_COLLECTIONS_SLUG_RECORDS_POST_003] Manage a record end to end: create, view, update and delete it; it is gone afterwards', async ({ api, data }) => {
      requireCredentials('admin');
      const input = data.entry('valid', 'TC_REQRES_APP_COLLECTIONS_SLUG_RECORDS_POST_003');
      // 1. create
      const created = await api.send({ method: 'POST', path: '/app/collections/{slug}/records', identity: 'default', body: input.body });
      expectStatus(created, [201]);
      expectJsonContentType(created);
      expectResponseTime(created, limits.responseTimeMs);
      expectSchema(created, S.AppCollectionsSlugRecordsPostResponse);
      expectEcho(input.body, created.json);
      const id = getAtPath(created.json, 'id');
      expect(['string', 'number'], 'create response returns an id').toContain(typeof id);
      const itemId = id as string | number;
      let deleted = false;
      try {
        // 2. read back - created data must be retrievable and identical
        const read = await api.send({ method: 'GET', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId } });
        expectStatus(read, [200]);
        expectSchema(read, S.AppCollectionsSlugRecordsRecordidGetResponse);
        expectEcho(input.body, read.json);
        // 3. full update
        const updated = await api.send({ method: 'PUT', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId }, body: input.updateBody });
        expectStatus(updated, [200]);
        expectEcho(input.updateBody, updated.json);
        const reread = await api.send({ method: 'GET', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId } });
        expectStatus(reread, [200]);
        expectEcho(input.updateBody, reread.json);
        // 4. partial update
        const patched = await api.send({ method: 'PATCH', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId }, body: input.patchBody });
        expectStatus(patched, [200]);
        expectEcho(input.patchBody, patched.json);
        // 5. delete, then the resource must be gone
        const removed = await api.send({ method: 'DELETE', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId } });
        expectStatus(removed, [204]);
        deleted = true;
        const gone = await api.send({ method: 'GET', path: '/app/collections/{slug}/records/{recordId}', identity: 'default', pathParams: { recordId: itemId } });
        expectStatus(gone, [404]);
      } finally {
        if (!deleted) await api.remove('app', itemId);
      }
    });

